let c = 0;
for (const x of w) {
  if (x.length > 2) c++;
}
console.log(c);   // 2

const m = [7, 8];
for (let i = 0; i < m.length; i++) {
  console.log(`№${i + 1}: ${m[i]}`);   // №1: 7, №2: 8
}

function howMany() {
  console.log(arguments.length);
}
howMany('x', 'y');   // 2

function multiplyAll() {
  let result = 1;
  for (let i = 0; i < arguments.length; i++) {
    result *= arguments[i];
  }
  return result;
}
console.log(multiplyAll(2, 3, 4));   // 24

function demo() {
  const copy = [];
  for (let i = 0; i < arguments.length; i++) {
    copy.push(arguments[i]);
  }
  console.log(copy.includes('b'));   // true для demo('a', 'b')
}
demo('a', 'b');

topics.intro:
**Суть.** Якщо параметр не передали, він дорівнює `undefined`. Можна задати значення за замовчуванням: `function f(name = 'гість')`. Воно використовується лише коли аргумент **не передано** (або передано undefined).

**Приклад на тему (інші значення, ніж у завданнях):**
```js
function hello(name = 'друже') {
  console.log(`Привіт, ${name}`);
}
hello('Іра');   // Привіт, Іра
hello();        // Привіт, друже
```

tasks.example:
function bye(who = 'всім') {
  console.log(`Бувай, ${who}`);
}
bye();        // Бувай, всім
bye('Макс');  // Бувай, Макс

function area(w, h = w) {
  return w * h;
}
console.log(area(3));      // 9
console.log(area(3, 5));   // 15

function pad(text, ch = '*') {
  return ch + text + ch;
}
console.log(pad('a'));        // *a*
console.log(pad('a', ''));    // a, порожній рядок теж значення

topics.intro:
**Суть.** Функцію можна записати в змінну: `const sum = function (a, b) { return a + b; };`. Викликається так само: `sum(1, 2)`. На відміну від `function sum() {}` (declaration), такий вираз **не можна викликати до рядка, де його оголошено**.

**Приклад на тему (інші значення, ніж у завданнях):**
```js
const double = function (n) {
  return n * 2;
};
console.log(double(4));   // 8
const copy = double;
console.log(copy(10));    // 20
```

